// SPDX-License-Identifier: MIT
// Emberkiln (Prismheart campaign), plain C++17 for the Unreal binding. A port of tools/minigames/emberkiln.py
// (unreal-team), which stays the rules authority. Seeding is CPython-compatible (DaedalusPyRandomCore.h,
// "emberkiln:<seed>:<difficulty>") and the only draws are randrange at setup; nothing is random after. Byte parity
// goes through engines/unreal/core-test/emberkiln_parity.txt (emberkiln_core_test.cpp), generated by
// tools/minigames/emberkiln_parity.py.
//
// Rules: an S x S kiln floor of clay tiles with firing targets 2..4 and a few stone cells. Each turn a coal goes on
// any cell: raw clay under it gains CoalHeat (2), each of its four neighbours gains SpreadHeat (1); stone and finished
// tiles take nothing but still pass the spread on. A tile at exactly its target glazes; past it, it cracks. Every
// tile glazed with no crack wins (+GlazeScore each, +CoalBonus per coal left); a crack on a finished floor or spent
// coals lose. The whole floor is allocation-free: fixed MaxSize x MaxSize arrays, noexcept throughout.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <array>
#include <cstdint>
#include <string>

namespace daedalus { namespace emberkiln {

inline const char* GameId() { return "emberkiln"; }
inline const char* Title() { return "Emberkiln"; }

constexpr int MaxSize = 9;
constexpr int CoalHeat = 2, SpreadHeat = 1;
constexpr int GlazeScore = 5, CrackScore = -3, CoalBonus = 2;
/** Tile codes beside the firing targets 2..4 (emberkiln.STONE / GLAZED / CRACKED). */
constexpr int Stone = 0, Glazed = -1, Cracked = -2;
constexpr int Targets[] = { 2, 3, 4 };
constexpr int TargetCount = 3;

struct Difficulty { const char* Name; int Size; int Stone; int Coals; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 5, 4, 19 }, { "normal", 6, 6, 27 }, { "hard", 7, 8, 36 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

struct Cell { int R = 0, C = 0; bool operator==(const Cell& O) const noexcept { return R == O.R && C == O.C; } };

/** The four neighbours in the rules' order: n, e, s, w. */
constexpr int NeighbourDR[] = { -1, 0, 1, 0 };
constexpr int NeighbourDC[] = { 0, 1, 0, -1 };

/** What one coal would do (Game.preview): tiles that glaze, tiles that crack, raw tiles merely warmed. */
struct Outcome { int Glazes = 0, Cracks = 0, Raised = 0; };

struct Game
{
	using Grid = std::array<std::array<int, MaxSize>, MaxSize>;

	const Difficulty* Diff = nullptr;
	Grid Target{};   // Stone / Glazed / Cracked or a firing target 2..4
	Grid Heat{};
	int Coals = 0, GlazedCount = 0, CrackedCount = 0;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, OffFloor, GameOver };

	int Size() const noexcept { return Diff ? Diff->Size : 0; }
	bool Inside(Cell X) const noexcept { return X.R >= 0 && X.R < Size() && X.C >= 0 && X.C < Size(); }
	int TargetAt(Cell X) const noexcept { return Target[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)]; }
	int HeatAt(Cell X) const noexcept { return Heat[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)]; }
	bool IsRaw(Cell X) const noexcept { return TargetAt(X) > 0; }

	/** Game.clay: tiles still to glaze. */
	int Raw() const noexcept
	{
		int N = 0;
		for (int R = 0; R < Size(); ++R) for (int C = 0; C < Size(); ++C) if (IsRaw({ R, C })) ++N;
		return N;
	}

	/** Game.fresh: no coal set yet, so the screen shows its tutorial rows. */
	bool FreshFloor() const noexcept { return Diff && Coals == Diff->Coals && !Over; }

	/** PrismGame.start + Game.setup. False on an unknown difficulty. Draw order: every target row-major, then stone. */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff || Diff->Size > MaxSize) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		const int S = Diff->Size;
		for (auto& Row : Target) Row.fill(Stone);
		for (auto& Row : Heat) Row.fill(0);
		for (int R = 0; R < S; ++R)
			for (int C = 0; C < S; ++C)
				Target[static_cast<size_t>(R)][static_cast<size_t>(C)] = Targets[Rng.RandRange(static_cast<std::uint32_t>(TargetCount))];
		int Placed = 0;
		while (Placed < Diff->Stone)
		{
			const int R = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(S)));
			const int C = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(S)));
			if (Target[static_cast<size_t>(R)][static_cast<size_t>(C)] == Stone) continue;
			Target[static_cast<size_t>(R)][static_cast<size_t>(C)] = Stone;
			++Placed;
		}
		Coals = Diff->Coals; GlazedCount = CrackedCount = 0;
		return true;
	}

	/** Game.heat_cell: +1 for a glaze, -1 for a crack, 0 otherwise. Stone and finished tiles take none. */
	int HeatCell(Cell X, int Amount) noexcept
	{
		int& T = Target[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)];
		if (T <= 0) return 0;
		int& H = Heat[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)];
		H += Amount;
		if (H == T) { T = Glazed; return 1; }
		if (H > T) { T = Cracked; return -1; }
		return 0;
	}

	/** Game.preview: what a coal at X would do, without placing it. False off the floor. */
	bool Preview(Cell X, Outcome& Out) const noexcept
	{
		Out = Outcome{};
		if (!Inside(X)) return false;
		const auto Consider = [&](Cell Y, int Amount) noexcept
		{
			if (!Inside(Y) || !IsRaw(Y)) return;
			const int After = HeatAt(Y) + Amount, T = TargetAt(Y);
			if (After == T) ++Out.Glazes;
			else if (After > T) ++Out.Cracks;
			else ++Out.Raised;
		};
		Consider(X, CoalHeat);
		for (int N = 0; N < 4; ++N) Consider({ X.R + NeighbourDR[N], X.C + NeighbourDC[N] }, SpreadHeat);
		return true;
	}

	/** Game.act. `Result` mirrors the Python result text. */
	Act Step(Cell X, Outcome& Did, std::string& Result)
	{
		Did = Outcome{};
		if (Over) return Act::GameOver;
		if (!Inside(X)) return Act::OffFloor;
		--Coals;
		const auto Apply = [&](Cell Y, int Amount) noexcept
		{
			if (!Inside(Y)) return;
			const int R = HeatCell(Y, Amount);
			if (R > 0) ++Did.Glazes;
			else if (R < 0) ++Did.Cracks;
		};
		Apply(X, CoalHeat);
		for (int N = 0; N < 4; ++N) Apply({ X.R + NeighbourDR[N], X.C + NeighbourDC[N] }, SpreadHeat);
		GlazedCount += Did.Glazes; CrackedCount += Did.Cracks;
		Score += GlazeScore * Did.Glazes + CrackScore * Did.Cracks;
		const std::string Head = std::to_string(X.R) + "," + std::to_string(X.C) + ": " + std::to_string(Did.Glazes) + " glazed, ";
		const int Left = Raw();
		if (Left == 0)
		{
			if (CrackedCount == 0)
			{
				Score += CoalBonus * Coals;
				Over = Won = true;
				Result = Head + "the whole floor shines";
				return Act::Ok;
			}
			Over = true; Won = false;
			Result = Head + std::to_string(Did.Cracks) + " cracked; the firing is spoiled";
			return Act::Ok;
		}
		if (Coals <= 0)
		{
			Over = true; Won = false;
			Result = Head + std::to_string(Did.Cracks) + " cracked; the coals are spent";
			return Act::Ok;
		}
		Result = Head + std::to_string(Did.Cracks) + " cracked, " + std::to_string(Left) + " raw";
		return Act::Ok;
	}

	/**
	 * Game.demo_action, the stoker: the coal that cracks least, then glazes most, then warms most raw tiles;
	 * ties by row, then column.
	 */
	Cell DemoAction() const noexcept
	{
		Cell Best{ 0, 0 }; int BestKey[3] = { 0, 0, 0 }; bool Found = false;
		for (int R = 0; R < Size(); ++R)
			for (int C = 0; C < Size(); ++C)
			{
				Outcome O;
				Preview({ R, C }, O);
				const int Key[3] = { O.Cracks, -O.Glazes, -O.Raised };
				if (!Found || KeyBefore(Key, BestKey))
				{
					Found = true; Best = { R, C };
					for (int K = 0; K < 3; ++K) BestKey[K] = Key[K];
				}
			}
		return Best;
	}

	/** Lexicographic "strictly less" on the stoker's three-part key. */
	static bool KeyBefore(const int* A, const int* B) noexcept
	{
		for (int K = 0; K < 3; ++K) if (A[K] != B[K]) return A[K] < B[K];
		return false;
	}

	/** Parity text: one digit per cell, rows joined by ';'. Glazed is 9, cracked 8, stone 0. */
	std::string FloorString() const
	{
		std::string Out;
		for (int R = 0; R < Size(); ++R)
		{
			if (R) Out.push_back(';');
			for (int C = 0; C < Size(); ++C)
			{
				const int T = TargetAt({ R, C });
				Out.push_back(T == Glazed ? '9' : T == Cracked ? '8' : static_cast<char>('0' + T));
			}
		}
		return Out;
	}
	std::string HeatString() const
	{
		std::string Out;
		for (int R = 0; R < Size(); ++R)
		{
			if (R) Out.push_back(';');
			for (int C = 0; C < Size(); ++C) Out.push_back(static_cast<char>('0' + HeatAt({ R, C })));
		}
		return Out;
	}
};

} } // namespace daedalus::emberkiln
